use crate::{model::*,unit_support::*,rules::*,bq047 as b};
fn entered()->(Game,String){let mut g=game();let id=field(&mut g,b::ID,0);g.enter_triggers(0,b::ID,&id,false);g.drive().unwrap();(g,id)}
#[test]fn bq047_original_closed_definition(){let c=crate::catalog::card(b::ID);assert!(!c.supported);assert_eq!(c.cost,4);assert_eq!(c.defense,Some(2));assert_eq!(c.permanent_icons.combat,2);assert_eq!(c.temporary_icons.investigation,1);assert_eq!(c.temporary_icons.influence,1);assert_eq!(b::definition().traits.kill,1);assert_current_serial_catalog();crate::rules::validate_definitions(crate::rules::definitions()).unwrap();}
#[test]fn bq047_forced_entry_is_respondable_and_destroys_original_region(){let(mut g,id)=entered();assert!(g.pending.is_none());assert_eq!(g.stack.last().unwrap().frame.as_ref().unwrap().ability_key,b::KEY);restore(&mut g);g.regions[0].cards.retain(|c|c.id!=id);crate::jc029_tests::pass_top(&mut g);assert!(g.regions[0].destroyed);restore(&mut g);}
#[test]fn bq047_replaced_region_never_redirects(){let(mut g,_)=entered();g.regions[0].card=g.make_card("DQJC115",0);crate::jc029_tests::pass_top(&mut g);assert!(!g.regions[0].destroyed);restore(&mut g);}
#[test]fn bq047_corrupt_frame_and_duplicate_continuation_rejected(){let(g,_)=entered();for n in 0..4{let mut bad=g.clone();let f=bad.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.steps.clear(),1=>f.source.source_region_instance=None,2=>f.source.card.definition="JC125".into(),_=>bad.effects.push_back(Effect::Frame{frame:Box::new(f.clone())})}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}}
#[test]fn bq047_real_paid_deploy_room_duplicate_and_restore(){use crate::abi112_review_play_tests::Trace;let mut g=game();fund(&mut g,0,"JC049",4);let id=held(&mut g,b::ID,0);let mut t=Trace::new_preserving_rng(g,"bq047-prepared-paid-deploy".into(),7400);t.action(0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});for _ in 0..32{if t.room.game.pending.is_none()&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break}t.pass();}assert!(t.room.game.regions[0].destroyed);let mut v=t.value();for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}if let Ok(path)=std::env::var("BQ047_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec(&v).unwrap()).unwrap();}}
#[test]fn bq047_rumor_accept_decline_and_restoration(){for seal in [false,true]{let mut g=game();let host=field(&mut g,"JC125",0);fund(&mut g,0,"JC084",3);let source=held(&mut g,"XG28",0);act(&mut g,0,Action{card_id:Some(source),region:Some(0),..Action::new("play")});crate::jc029_tests::pass_top(&mut g);let source=g.attachments.iter().find(|a|a.card.definition=="XG28").unwrap().card.id.clone();g.players[0].deck=vec![g.make_card(b::ID,0)];g.turn+=1;g.begin_window(Window::Prepare);g.drive().unwrap();choose(&mut g,vec![source]);for _ in 0..32{if g.pending.is_some(){break}pass(&mut g);}assert_eq!(g.pending.as_ref().unwrap().choice.kind,"rumor");restore(&mut g);choose(&mut g,if seal{vec![host.clone()]}else{vec![]});assert_eq!(g.sealed_cards.iter().filter(|s|s.host_id==host&&s.card.definition==b::ID).count(),usize::from(seal));assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition==b::ID).count(),usize::from(!seal));restore(&mut g);}}
#[test]fn bq047_natural_private_deck_entry_export(){use crate::{deck,catalog,abi112_review_play_tests::Trace};fn start(seed:u64)->(Game,deck::DeckDraft){let mut d=deck::preset("watchers").unwrap();d.society_id=None;d.core_card_id=None;d.cards=vec![catalog::DeckEntry{card_id:b::ID.into(),count:3},catalog::DeckEntry{card_id:"JC049".into(),count:3},catalog::DeckEntry{card_id:"JC125".into(),count:44}];let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==b::ID).unwrap().supported=true;let d=deck::validate_with_registry(d,&cards,&catalog::catalog().societies).unwrap();let mut other=d.clone();other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("bq047".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}let(seed,g,d)=(1..1025).find_map(|seed|{let(g,d)=start(seed);[b::ID,"JC049"].iter().all(|id|g.players[0].hand.iter().any(|c|c.definition==*id)).then_some((seed,g,d))}).unwrap();let mut t=Trace::new_preserving_rng(g,"bq047-natural-paid-entry".into(),7401);let mut played=false;for _ in 0..1200{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());continue}if played&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break}let g=&t.room.game;let legal=g.legal_actions(0);let a=if g.players[0].assets.len()<4{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==if g.players[0].assets.is_empty(){"JC049"}else{"JC125"})))}else{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.region==Some(0)&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==b::ID)))};if let Some(a)=a{let a=a.action.clone();played|=a.kind=="deploy";t.action(0,a);}else{t.pass();}}assert!(played&&t.room.game.regions[0].destroyed);let mut v=t.value();v["construction"]=serde_json::json!({"deck":d,"seed":seed,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed);s["duplicate"]=serde_json::to_value(d).unwrap();}if let Ok(p)=std::env::var("BQ047_NATURAL_OUT"){std::fs::write(p,serde_json::to_vec(&v).unwrap()).unwrap();}}
